import{_ as t,o as s,c as i,a2 as e}from"./chunks/framework.Cvf4Fkn6.js";const c=JSON.parse('{"title":"设置页详解","description":"","frontmatter":{},"headers":[],"relativePath":"guide/settings.md","filePath":"guide/settings.md","lastUpdated":1794577080000}'),r={name:"guide/settings.md"};function o(l,a,n,h,p,d){return s(),i("div",null,[...a[0]||(a[0]=[e('<h1 id="设置页详解" tabindex="-1">设置页详解 <a class="header-anchor" href="#设置页详解" aria-label="Permalink to &quot;设置页详解&quot;">​</a></h1><p>点菜单栏 WTidy 图标 →「设置…」打开设置窗口，四个标签页对齐原版：<strong>布局 / 行为 / 定位 / 关于</strong>；窗口底部有「开机自动启动」开关。</p><h2 id="布局" tabindex="-1">布局 <a class="header-anchor" href="#布局" aria-label="Permalink to &quot;布局&quot;">​</a></h2><p>布局列表管理 + 网格编辑器 + 每区域快捷键录制，详见<a href="./layouts.html">布局自定义</a>与<a href="./hotkeys.html">快捷键</a>。</p><h2 id="行为" tabindex="-1">行为 <a class="header-anchor" href="#行为" aria-label="Permalink to &quot;行为&quot;">​</a></h2><ul><li><p><strong>⌥ 选项按钮</strong>：二选一——「按住 ⌥ 隐藏布局图标」或「按住 ⌥ 显示布局图标」，临时让图标条让路</p></li><li><p><strong>显示菜单栏状态图标</strong>：关闭后菜单栏图标随菜单一起消失——WTidy 没有 Dock 图标，届时将无法从菜单打开设置与退出。如需恢复，在终端执行：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">defaults</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> write</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.allblue.wtidy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> showStatusIcon</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -bool</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> true</span></span></code></pre></div><p>然后重启 WTidy（活动监视器退出进程再重新打开）。</p></li><li><p><strong>在布局图标上显示名称</strong>：图标条上叠加布局名称标注</p></li><li><p><strong>窗口未能调整尺寸时显示警告</strong>：个别应用拒绝调整尺寸时给出反馈</p></li></ul><blockquote><p>拖拽分屏、全局快捷键、吸附动画是常开行为，不设开关——与原版保持一致。</p></blockquote><h3 id="图标条配色" tabindex="-1">图标条配色 <a class="header-anchor" href="#图标条配色" aria-label="Permalink to &quot;图标条配色&quot;">​</a></h3><p>四套主题任选：<strong>墨蓝 / 石墨 / 青碧 / 紫罗兰</strong>，即时生效于图标条与悬停高亮。</p><h3 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h3><p>图标条背景二选一：<strong>默认背景</strong>（随配色主题的深色底）或<strong>使用桌面壁纸</strong>（抓取当前桌面壁纸 + 蒙板，与桌面融为一体）。</p><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><ul><li><strong>排列方向</strong>：图标条横向排列或纵向排列</li><li><strong>屏幕位置</strong>：可视化屏幕预览 + 滑块微调（与排列方向联动——横向排列调上下、纵向排列调左右）</li><li><strong>尺寸</strong>：最大宽度、屏幕边距。数值为整条图标条的总宽度；单图标宽 = 可用宽度 ÷ 布局数（基准 150pt，下限 90pt）</li><li><strong>窗口间隙</strong>：贴合 / 4pt / 8pt / 12pt——贴合为窗口完全贴齐；间距让相邻窗口留出呼吸感</li></ul><h2 id="关于" tabindex="-1">关于 <a class="header-anchor" href="#关于" aria-label="Permalink to &quot;关于&quot;">​</a></h2><p>显示应用图标与版本号、日志完整路径，并提供「打开日志」按钮。</p><h2 id="可靠性" tabindex="-1">可靠性 <a class="header-anchor" href="#可靠性" aria-label="Permalink to &quot;可靠性&quot;">​</a></h2><p>WTidy 与原版的核心差异都在看不见的地方：</p><ul><li><strong>看门狗自愈</strong>：切换前台应用、屏幕唤醒、显示器插拔、Space 切换时事件驱动重挂监听；每 10 秒心跳校验；每 60 秒无条件重建监听链——睡眠唤醒后「拖拽失灵」从此不需要重启应用</li><li><strong>状态可见</strong>：菜单栏图标双态（🟢 正常监听 / ⚠️ 缺权限闪烁），状态行实时显示「最近吸附」，静默失效看得见</li><li><strong>现代登录项</strong>：SMAppService（BTM 原生）实现开机自启，不依赖已失效的旧机制</li><li><strong>全程日志</strong>：<code>~/Library/Logs/WTidy.log</code>（512KB 自动轮转），出问题可追溯</li></ul>',18)])])}const u=t(r,[["render",o]]);export{c as __pageData,u as default};
